import { Airline } from "./types";
import { airports } from "./airports";

const a = airports;

function route(from: string, to: string) {
  if (!a[from] || !a[to]) {
    console.warn(`Missing airport: ${!a[from] ? from : to}`);
    return null!;
  }
  return { from: a[from], to: a[to] };
}

